void MOD_mkRegRenamingTable::dump_VCD(tVCDDumpType dt,
				      unsigned int levels,
				      MOD_mkRegRenamingTable &backing)
{
  vcd_defs(dt, backing);
  vcd_prims(dt, backing);
}

